# -*- coding: utf-8 -*-
"""Life, liveliness and staying workable: VIV with its VITA branch."""
import json
from pathlib import Path
from lesson_authoring import entry as E
H=[['拉丁 vīvus、vīvere；相关 vīta','活着的、生活；生命']]
V=H+[['拉丁 vividus → 法语 vivide / 直接拉丁借入 → 英语 vivid','充满生命力的 → 鲜明、生动的']]
RE=H+[['拉丁 re- + vīvere → revīvere；古法语 revivre','再活起来；恢复'],['中古英语 → revive','恢复意识或活力；重新兴起']]
VA=[['拉丁 vīta → 法语 vie','生命'],['法语 vie + -able → viable → 英语 viable','能生活下去的 → 能成功运行的']]
CO=H+[['拉丁 con- + vīvere → convīvere → convīvium','共同生活、宴饮 → 宴会'],['后期拉丁 convīviālis；法语 convivial → 英语 convivial','宴饮的 → 欢乐友好的']]
def D(h,a,b):return h+[[a,b]]
W=[
E('viable','/ˈvaɪəbəl/','能够存活的；切实可行的；能持续运作的','先问生命能否继续维持，再把问题换成一个方案：“它真的撑得住、运行得下去吗？”','法语 vie“生命”+ -able，接拉丁 vīta；不是把英语 via“经由”加 -able。',VA,'viable seeds 是能发芽生长的种子；a viable plan 是具备实际成功条件的计划。通常比“想得到”更进一步，重在能运行、能存续。','a viable option；economically viable；viable seeds。','possible 只需有可能；viable 进一步强调在具体条件下能够成功或持续。',('We need a viable plan, not just an attractive idea.','我们需要切实可行的计划，而不只是一个好听的想法。'),('The test showed that most of the seeds were still viable.','测试显示大多数种子仍有发芽能力。'),sources=['https://www.etymonline.com/word/viable']),
E('revival','/rɪˈvaɪvəl/','复苏；复兴；重新上演；宗教复兴活动','原本沉寂、衰落或退到一旁的东西重新活跃，整个回来的过程就是 revival。','revive + -al；英语名词派生。',D(RE,'英语 revive + -al → revival','重新活跃 → 复苏、复兴'),'可说工艺、风格重新流行，也可指旧剧重新演出。宗教语境另有信仰复兴及相关集会的专门用法。','a revival of interest；an economic revival；a stage revival。','recovery 常说从损伤或低谷恢复；revival 常突出某事重新活跃、重新受关注。',('The town has seen a revival of traditional crafts.','小镇的传统手工艺重新兴盛起来。'),('The theatre announced a revival of the musical.','剧院宣布将重新上演这部音乐剧。')),
E('vivid','/ˈvɪvɪd/','生动鲜明的；鲜艳的；记忆清晰的','一个画面不是模模糊糊，而是细节和色彩像活着一样跳到眼前，这就是 vivid。','拉丁 vividus 来自 vīvus“活着的”，经法语或直接借入。',V,'vivid colours 是鲜明强烈的颜色；a vivid memory 是主观感受清楚的记忆。清楚不等于事实一定准确，梦也能很 vivid。','a vivid memory；vivid colours；a vivid description。','accurate 是准确；vivid 是感受鲜明。故事可以编造得很生动，记忆也可能清晰但有误。',('She gave a vivid description of the crowded market.','她把拥挤的市场描写得十分生动。'),('I still have a vivid memory of that afternoon.','我对那个下午仍记忆犹新。'),sources=['https://www.etymonline.com/word/vivid']),
E('revive','/rɪˈvaɪv/','使苏醒；恢复活力；重新兴起、启用','re- 把生命力带回来：人恢复精神，老计划重新启动，兴趣再次燃起，都能借这个动作表达。','拉丁 revīvere“再活起来”，经古法语 revivre 等路线传入。',RE,'既可及物 revive interest，也可不及物 the tradition revived。现实语境常是恢复意识、活力或活动，并不一定表示死者复生。','revive interest in；revive a tradition；revive an old plan。','survive 是经历危险后继续活着；revive 是从低落、停顿等状态恢复过来，方向不同。',('The festival helped revive interest in local music.','音乐节帮助人们重新关注本地音乐。'),('After a short rest, her energy began to revive.','稍作休息后，她开始恢复精力。'),sources=['https://www.etymonline.com/word/revive']),
E('viability','/ˌvaɪəˈbɪləti/','存活能力；可行性；持续运行的可能性','不只问“看起来好不好”，而是检查支撑它活下去或运转下去的条件是否够用。','法语 viabilité 接 viable；现代也可分析为 viable + -ity，历史上保留法语名词借入路线。',[VA[0],['法语 viable → viabilité → 英语 viability','能存续的 → 存续能力、可行性']],'可讨论项目、企业模式、种子或细胞。不同对象有不同评价标准，不能只凭一个乐观设想就判断 viability。','assess viability；commercial viability；seed viability。','feasibility 常问能否做成；viability 常兼顾能否持续有效运行，不过具体语境中两者会重叠。',('The team assessed the long-term viability of the project.','团队评估了项目长期运行的可行性。'),('Storage conditions can affect seed viability.','储存条件会影响种子的生活力。'),sources=['https://www.etymonline.com/word/viability']),
E('vividly','/ˈvɪvɪdli/','生动地；鲜明地；清晰地','一个故事说得让人能在脑中看见，或一段记忆像刚发生过，都能用 vividly 描述。','vivid + -ly；英语副词。',D(V,'英语 vivid + -ly → vividly','鲜明、生动的 → 鲜明地、生动地'),'常见 vividly remember、vividly describe，也可用在 illustrated 等呈现方式上。强调印象强，不自动担保描述真实。','remember vividly；describe vividly；vividly illustrated。','clearly 可以只说清楚、无歧义；vividly 更带画面、细节和强烈感受。',('I vividly remember the smell of fresh bread in that shop.','我清楚记得那家店里新鲜面包的香味。'),('The novel vividly portrays life in a crowded city.','小说生动描绘了拥挤城市中的生活。')),
E('vivacious','/vɪˈveɪʃəs/〔也读 /vaɪˈveɪʃəs/〕','活泼的；有生气的；热情有感染力的','一个人说话有表情、回应有精神，让周围气氛跟着活起来，这种鲜活劲儿就是 vivacious。','拉丁 vīvāx，词干 vīvāc-，与 vīvere“活着”相连；英语以 -ous 形式形成形容词。',[H[0],['拉丁 vīvāx / vīvāc- → 英语 vivacious','生命力强的 → 活泼有生气的']],'多描述人的性格、神态或谈吐，语气常是赞许。不是专门指某个性别，也不要求一直大声说话。','a vivacious personality；a vivacious host。','energetic 更广泛说精力充沛；vivacious 常突出活泼神态和交往中的生气。',('Her vivacious manner put the guests at ease.','她活泼热情的举止让客人放松下来。'),('He was a vivacious storyteller who made every character memorable.','他讲故事很有生气，把每个人物都讲得令人难忘。'),sources=['https://www.etymonline.com/word/vivacious']),
]
W.extend([
E('convivial','/kənˈvɪviəl/','欢乐友好的；聚会气氛融洽的；好交际的','一桌人边吃边聊，彼此放松、气氛热络，便是 convivial 的典型画面。','拉丁 con- 一起 + vīvere，形成 convīvere、convīvium“宴会”，再经 convīviālis 等形式传入。',CO,'既可形容聚会、氛围，也可形容善于使交往愉快的人。它带着共享愉快时光的意味，不只是房间里有很多人。','a convivial atmosphere；a convivial evening；a convivial host。','crowded 只说人多；convivial 说相处愉快。安静的小聚也可以很 convivial。',('The dinner ended in a convivial atmosphere.','晚餐在愉快融洽的气氛中结束。'),('Our host was convivial without dominating the conversation.','主人热情健谈，却没有霸着谈话不放。'),sources=['https://www.etymonline.com/word/convivial','https://en.wiktionary.org/wiki/convivial#English']),
E('vivisection','/ˌvɪvɪˈsekʃən/','活体解剖；对活体进行的侵入性实验','vivi- 指仍活着，section 接切开；这个术语把“研究对象处于活体状态”放在最前面。','拉丁 vīvus 活着的 + sectiō 切开，近代科学构词；法语也有 vivisection。',[H[0],['拉丁 vīvus 与 sectiō 组合 → vivisection','活着 + 切开 → 活体解剖']],'用于实验史、伦理或研究讨论，通常涉及活体的切开或侵入性处理。dissection 本身只说解剖，不自动表示对象是活的。','the history of vivisection；a debate over vivisection。','autopsy 通常指死后剖验；vivisection 明确强调活体，不能因都涉及解剖就混用。',('The book examines the history of vivisection.','这本书考察了活体解剖的历史。'),('The lecture discussed ethical debates surrounding vivisection.','讲座讨论了围绕活体解剖的伦理争议。')),
E('unviable','/ʌnˈvaɪəbəl/','无法存活的；不可行的；难以持续运作的','viable 表示能撑得下去，un- 把它否定：缺少必要条件，这条路走不通。','un- 不 + viable；在英语中形成否定形容词。',D(VA,'英语 un- + viable → unviable','能够存续的 → 无法存续、不可行的'),'可说项目、模式等，也可在生物语境描述不能存活的对象。日常项目讨论里，比简单说“不喜欢”更强，声称的是实际运行条件不足。','financially unviable；an unviable proposal。','unpopular 是不受欢迎；unviable 是不可行，不受欢迎的方案仍可能运作，反之也一样。',('Without a reliable water supply, the plan is unviable.','没有可靠供水，这个计划不可行。'),('Rising costs made the service financially unviable.','成本上涨使这项服务在财务上难以持续。')),
E('vivacity','/vɪˈvæsəti/','活泼；生气；谈吐举止中的活力','不只身体有力气，而是神情、反应和谈话都带着鲜活劲儿；把这种特点当作名词，就是 vivacity。','拉丁 vīvācitās，来自 vīvāx；经法语或直接借入，英语名词出现较早，不从后来的 vivacious 倒推。',[H[0],['拉丁 vīvāx → vīvācitās；古法语 vivacite','生命力强的 → 活力、敏捷'],['英语 vivacity','性格、谈吐或表现中的活泼生气']],'常用于人物描写，也可说表演、音乐的活泼感。通常是不可数性质名词，不是计数几单位体力。','the vivacity of her conversation；perform with vivacity。','vitality 更广泛说生命力和活力；vivacity 常突出外在表现出的灵动、活泼。',('Her conversation lost none of its usual vivacity.','她的谈吐仍像往常一样活泼有趣。'),('The musicians played with wit and vivacity.','乐手们的演奏机趣盎然、充满生气。'),sources=['https://www.etymonline.com/word/vivacity']),
E('vividness','/ˈvɪvɪdnəs/','鲜明程度；生动性；清晰强烈的感受','有的记忆只剩轮廓，有的连颜色、声音都像在眼前；后者的 vividness 更强。','vivid + -ness；英语性质名词。',D(V,'英语 vivid + -ness → vividness','鲜明的 → 鲜明、生动的程度'),'可说描写、梦境、色彩或记忆。衡量的是主观印象强弱，而非直接衡量真实度。','the vividness of a memory；colour vividness；vividness of description。','accuracy 是准确性；vividness 是鲜明程度，不能用“记得真清楚”替代事实核对。',('The vividness of the dream stayed with her all morning.','那个梦鲜明的感受整个上午都留在她脑中。'),('The vividness of the description helped readers imagine the room.','描写的生动性帮助读者想象房间的样子。')),
E('conviviality','/kənˌvɪviˈæləti/','欢乐融洽的气氛；愉快交往；好交际','把 convivial 那种边聊边笑、彼此自在的状态整体说出来，就是 conviviality。','convivial + -ity；英语名词构词。',D(CO,'英语 convivial + -ity → conviviality','欢乐友好的 → 愉快融洽的交往状态'),'常用于描述聚会、公共空间或人际相处。未必涉及饮酒，也不等于每个人都很外向。','an atmosphere of conviviality；a sense of conviviality。','sociability 常说乐于交往的倾向；conviviality 更常让人想到交往时欢乐融洽的气氛。',('The shared meal created a sense of conviviality.','一起吃饭营造了愉快融洽的气氛。'),('The café is valued for its warmth and conviviality.','这家咖啡馆因温暖亲切、便于愉快交往而受到喜爱。')),
E('victual','/ˈvɪtəl/','食物、粮食〔常用复数 victuals〕；供应粮食','维持生命要有吃的，拉丁语便从“生活”走向“生活所需的食物”，最后来到这个较旧的英语词。','拉丁 vīvere → vīctus“生计、食物”→ vīctuālia，经法语 vitaile 传入；后来拼写恢复 c，但读音没有读出 c。',[H[0],['拉丁 vīctus → vīctuālia → 古法语 vitaile','维持生命的食物 → 食品、补给'],['中古英语 vitaile / vitailen → victual〔名词、动词〕','粮食；供应粮食；拼写后来参照拉丁语调整']],'常见 victuals，读 /ˈvɪtəlz/，不是按字母念成“维克丘尔斯”。动词常见于旧航海、军事文字，指给船只或人员备足食物。','food and victuals〔较旧〕；victual a ship；a supply of victuals。','victual 中的 vict- 来自生活、生计这支；victory 的 vict- 接征服，不能看到相同字母就并成同一个直接来源。',('The ship carried enough victuals for the voyage.','船上带了足够这次航行食用的粮食。'),('The crew had to victual the ship before departure.','船员必须在出发前给船备足食品。'),sources=['https://www.etymonline.com/word/victual','https://en.wiktionary.org/wiki/victual#English']),
])
ROOT=dict(id='C1653',meaning='活着、生活；生动、有活力；能存续',core='VIV = LIVE / ALIVE',image='生命力可以留在身体里，也能借给故事和计划：活得下去是 viable，恢复活力是 revive，画面鲜明得像活过来是 vivid，一群人愉快相聚便能理解 convivial。',intro='拉丁 vīvere“活着、生活”和 vīvus“活的”是主干；vīta“生命”是相关词形，viable、viability 走的是法语 vie 这条旁支。先把这些都放在生命的意象下，再分清各词实际路线。',forms='re- + vīvere 是重新恢复；survive 的 sur- 接拉丁 super-，强调经历之后继续活着；con- 引到共同宴饮。vivacity、viability 保留早期名词借入路线，不能仅凭现代相似形容词来倒排历史。',branches=[['继续存活','survive, survival, survivor, survivable, survivability'],['能不能存续','viable, viability, unviable'],['重新活跃','revive, revival'],['生动活泼','vivid, vividly, vividness, vivacious, vivacity'],['共同宴饮与维生','convivial, conviviality, victual'],['活体科学术语','vivisection']],contrasts='vivid 不保证准确；vivacious 不只是体力充沛。viable 的生命来源与 via“道路”不是同一直接来源。victual 与 victory 中形似的 vict- 要分开。',practice='A vivid description revived our interest in the project, but we still had to check whether it was viable.\n\n生动的描述重新激起了我们对项目的兴趣，但我们仍需检查它是否可行。',words=[w['word'] for w in W]+['survive','survival','survivor','survivable','survivability'])
if __name__=='__main__':
 t=Path(__file__).resolve().parents[1]/'.cache/batch200/drafts/root'
 for k,v in [('roots',[ROOT]),('words',W)]: (t/f'{k}_batch200_root_viv.json').write_text(json.dumps(v,ensure_ascii=False,indent=2))
 print(len(W),'individually authored words')
